{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R01-01",
   "status": "OK",
   "label": "청소년 통장 가입 대상",
   "source": {
    "quote": "만 19세 미만 실명의 개인"
   },
   "condition": {
    "==": [
     {
      "var": "customer.is_youth"
     },
     true
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "real_name"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-02",
   "status": "OK",
   "label": "청소년 통장 가입 대상",
   "source": {
    "quote": "개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
   },
   "condition": {
    "and": [
     {
      "var": "customer.is_youth"
     },
     {
      "not": {
        "exists": [
         {
          "var": "customer.is_individual_business"
         }
        ]
       }
      }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-03",
   "status": "OK",
   "label": "청소년 통장 가입 대상",
   "source": {
    "quote": "「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
   },
   "condition": {
    "and": [
     {
      "var": "customer.is_youth"
     },
     {
      "not": {
        "exists": [
         {
          "var": "customer.has_multiple_accounts"
         }
        ]
       }
      }
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "single_account"
   }
  }
 ]
}

