{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R07-01",
   "status": "OK",
   "label": "저금통 최대 금액 한도",
   "source": {
    "quote": "저금통 금액 설정은 최대 100만원(1만원 단위)까지 가능"
   },
   "condition": {
    "<=": [
     {
      "value": 1000000
     },
     {
      "var": "account.reserved_amount"
     }
    ]
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": 1000000
   }
  },
  {
   "rule_id": "R-KBYY-S2-R07-02",
   "status": "OK",
   "label": "저금통 금리 적용",
   "source": {
    "quote": "연 1.9% (최대 100만원까지)"
   },
   "condition": {
    "and": [
     {
      "exists": [
       {
        "var": "account.reserved_amount"
       }
      ]
     },
     {
      ">=": [
       {
        "value": 0
       },
       {
        "var": "account.reserved_amount"
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1.9,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  }
 ]
}

