{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R12",
   "status": "OK",
   "label": "KB국민카드 결제실적 수수료면제",
   "source": {
    "quote": "전월 중 이 통장에서 KB국민카드(신용/체크/KB국민비씨 카드포함) 결제실적(현금서비스 포함)이 있는 경우"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    ">": [
     {
      "count_events": {
       "event": "CARD_USAGE",
       "within": {
        "ref": "$window"
       }
      }
     },
     0
    ]
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "EBANK_TRANSFER",
    "value": 0
   }
  },
  {
   "rule_id": "R-KBYY-S2-R12-02",
   "status": "OK",
   "label": "신규/전환일 수수료면제",
   "source": {
    "quote": "이 통장의 신규(전환)일로부터 다음 다음 달 10일까지는 은행 거래실적에 관계없이 면제"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.switch_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.switch_date",
       "offset_months": 2,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "within": {
     "ref": "$window"
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "ATM_TRANSFER",
    "value": 0
   }
  }
 ]
}

