   "status": "OK",
   "label": "예금잔액 미달 및 무거래 거래제한",
   "source": {
    "quote": "예금잔액이 10,000원 미만이며, 1년 이상 입출금 거래가 없는 계좌"
   },
   "condition": {
    "and": [
     {
      "<": [
       {
        "var": "account.balance"
       },
       10000
      ]
     },
     {
      ">=": [
       {
        "count_events": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         }
        }
       },
       0
      ]
     }
    ]
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": -12,
       "day": "last"
      }
     }
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R19-02",
   "status": "OK",
