{
 "rules": [
  {
   "rule_id": "R-KBONE-S2-R16-01",
   "status": "OK",
   "label": "예금잔액 미만 및 무거래 거래제한",
   "source": {
    "quote": "예금잔액이 10,000원 미만이며, 1년이상 입출금거래가 없는 계좌"
   },
   "condition": {
    "and": [
     {
      "<": [
       {
        "var": "account.balance"
       },
       10000
      ]
     },
     {
      ">=": [
       {
        "count_events": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$window"
         }
        }
       },
       0
      ]
     }
    ]
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
